class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now } = {}) {
    if (typeof capacity !== 'number' || capacity <= 0 || !Number.isFinite(capacity)) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0 || !Number.isFinite(refillPerSecond)) {
      throw new RangeError('refillPerSecond must be a non-negative finite number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.now = now;

    this.tokens = capacity;
    this.lastRefillTime = this.now();
    this.lastMaxTime = this.now();
  }

  _refill() {
    const currentTime = this.now();

    // Eğer saat geri giderse, dolum için geçen süreyi 0 kabul et
    if (currentTime > this.lastMaxTime) {
      this.lastMaxTime = currentTime;
    } else {
      // Saat geri gitmiş veya aynı kalmış; dolum yapma
      return;
    }

    // En son başarılı dolum zamanından itibaren ne kadar zaman geçti?
    // Ancak sadece gerçek zaman ilerlediyse (currentTime > lastRefillTime)
    if (currentTime > this.lastRefillTime) {
      const elapsedSeconds = (currentTime - this.lastRefillTime) / 1000;
      const refillAmount = elapsedSeconds * this.refillPerSecond;

      this.tokens = Math.min(this.capacity, this.tokens + refillAmount);
      this.lastRefillTime = currentTime;
    }
  }

  tryTake(n = 1) {
    if (typeof n !== 'number' || n <= 0 || !Number.isFinite(n)) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this.tokens;
  }

  msUntil(n = 1) {
    if (typeof n !== 'number' || n <= 0 || !Number.isFinite(n)) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this.tokens >= n) {
      return 0;
    }

    if (this.refillPerSecond <= 0 || n > this.capacity) {
      return Infinity;
    }

    const needed = n - this.tokens;
    const secondsNeeded = needed / this.refillPerSecond;
    return Math.ceil(secondsNeeded * 1000);
  }
}

module.exports = { TokenBucket };

