node -e "const { TokenBucket } = require('./kova.js');
const assert = require('assert');

function test() {
  // 1. Temel Başlangıç ve Dolum
  let currentTime = 1000;
  const getNow = () => currentTime;
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: getNow });

  assert.strictEqual(bucket.available(), 10, 'Başlangıçta kova dolu olmalı');

  // 2. tryTake testi
  assert.strictEqual(bucket.tryTake(5), true, '5 jeton alınabilmeli');
  assert.strictEqual(bucket.available(), 5, '5 jeton kalmalı');
  assert.strictEqual(bucket.tryTake(6), false, 'Yetersiz jeton false dönmeli');
  assert.strictEqual(bucket.available(), 5, 'Hatalı denemede jeton azalmamalı');

  // 3. Zamanla Dolum
  currentTime += 2000; // 2 saniye geçsin
  assert.strictEqual(bucket.available(), 7, '2 saniyede 2 jeton dolmalı'); // 5 + (2 * 1)

  // 4. msUntil testi
  // 3 jeton lazım, şu an 7 var -> 0 ms
  assert.strictEqual(bucket.msUntil(3), 0);
  // 10 jeton lazım, şu an 7 var -> 3 jeton lazım. Hız 1/sn ise 3 saniye = 3000ms
  assert.strictEqual(bucket.msUntil(10), 3000);
  // Kapasite üstü talep
  assert.strictEqual(bucket.msUntil(11), Infinity);

  // 5. Saat geri gitme testi
  currentTime -= 5000; // Saat 5 saniye geri gitti
  assert.strictEqual(bucket.available(), 7, 'Saat geri giderse jeton azalmamalı');

  // 6. Geçersiz değerler (RangeError)
  try { bucket.tryTake(-1); assert.fail(); } catch (e) { assert.strictEqual(e.name, 'RangeError'); }
  try { new TokenBucket({ capacity: -1, refillPerSecond: 1 }); assert.fail(); } catch (e) { assert.strictEqual(e.name, 'RangeError'); }
  try { new TokenBucket({ capacity: 10, refillPerSecond: -1 }); assert.fail(); } catch (e) { assert.strictEqual(e.name, 'RangeError'); }
  try { bucket.msUntil(Infinity); assert.fail(); } catch (e) { assert.strictEqual(e.name, 'RangeError'); }

  console.log('Tüm testler başarıyla geçti!');
}

test();"

